SELECT cnn.pedon_key,cnn.site_key,cnn.pedlabsampnum,cnn.upedonid,cnn.samp_name,cnn.samp_class_type,cnn.samp_classdate,cnn.samp_classification_name,cnn.samp_taxorder,cnn.samp_taxsuborder,cnn.samp_taxgrtgroup,cnn.samp_taxsubgrp,cnn.corr_name,cnn.corr_class_type,cnn.corr_classdate,cnn.corr_classification_name,cnn.corr_taxorder,cnn.corr_taxsuborder,cnn.corr_taxgrtgroup,cnn.corr_taxsubgrp,cnn.SSL_name,cnn.SSL_class_type,cnn.SSL_classdate,cnn.SSL_classification_name,cnn.SSL_taxorder,cnn.SSL_taxsuborder,cnn.SSL_taxgrtgroup,cnn.SSL_taxsubgrp FROM lab_combine_nasis_ncss cnn INNER JOIN lab_area s ON cnn.state_key=s.area_key WHERE s.area_code='TX'